 private UUID id; private Long version; private String code,name,description,merchantCodes,categoryCodes; private PromotionType promotionType; private PromotionRewardType rewardType; private BigDecimal rewardValue,minTransactionAmount; private Integer maxRedemptions,redemptionCount; private PromotionStatus status; private LocalDateTime startDate,endDate,createdAt,updatedAt;
 public UUID getId(){return id;} public void setId(UUID v){id=v;} public Long getVersion(){return version;} public void setVersion(Long v){version=v;} public String getCode(){return code;} public void setCode(String v){code=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public PromotionType getPromotionType(){return promotionType;} public void setPromotionType(PromotionType v){promotionType=v;} public PromotionRewardType getRewardType(){return rewardType;} public void setRewardType(PromotionRewardType v){rewardType=v;} public BigDecimal getRewardValue(){return rewardValue;} public void setRewardValue(BigDecimal v){rewardValue=v;} public Integer getMaxRedemptions(){return maxRedemptions;} public void setMaxRedemptions(Integer v){maxRedemptions=v;} public Integer getRedemptionCount(){return redemptionCount;} public void setRedemptionCount(Integer v){redemptionCount=v;} public BigDecimal getMinTransactionAmount(){return minTransactionAmount;} public void setMinTransactionAmount(BigDecimal v){minTransactionAmount=v;} public String getMerchantCodes(){return merchantCodes;} public void setMerchantCodes(String v){merchantCodes=v;} public String getCategoryCodes(){return categoryCodes;} public void setCategoryCodes(String v){categoryCodes=v;} public PromotionStatus getStatus(){return status;} public void setStatus(PromotionStatus v){status=v;} public LocalDateTime getStartDate(){return startDate;} public void setStartDate(LocalDateTime v){startDate=v;} public LocalDateTime getEndDate(){return endDate;} public void setEndDate(LocalDateTime v){endDate=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} public LocalDateTime getUpdatedAt(){return updatedAt;} public void setUpdatedAt(LocalDateTime v){updatedAt=v;}
